import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadCochinData(){const e=readFileSync(resolve(__dirname,"../../cochin-kingdom-explorer/cochin-data.js"),"utf-8");return new Function(e+"\nreturn { COCHIN_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Kingdom of Cochin Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadCochinData()}),describe("COCHIN_INFO metadata",()=>{it("contains correct Kingdom of Cochin attributes",()=>{expect(e.COCHIN_INFO.id).toBe("cochin-kingdom"),expect(e.COCHIN_INFO.name).toContain("Kingdom of Cochin"),expect(e.COCHIN_INFO.period).toContain("1102"),expect(e.COCHIN_INFO.portHub).toContain("Arabian Sea")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.COCHIN_INFO.quickStats)).toBe(!0),expect(e.COCHIN_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers including Sakthan Thampuran",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.maritimeTrade).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.architecture).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.culturalHarmony).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.thrissurPooram).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});